sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float scale;
uniform float2 offset;
uniform float mirror;
half4 main(float2 coord) {
    float3 a = fromLayer * float3(0.0, 0.0, 1.0);
    float3 b = fromLayer * float3(layer, 1.0);
    float2 lo = min(a.xy / a.z, b.xy / b.z);
    float2 hi = max(a.xy / a.z, b.xy / b.z);
    bool turned = abs(fromLayer[0].y) + abs(fromLayer[1].x) + abs(fromLayer[0].z) + abs(fromLayer[1].z) > 0.0001;
    bool inside = lo.x > -0.5 && lo.y > -0.5 && hi.x < size.x + 0.5 && hi.y < size.y + 0.5;
    bool cut = lo.x > 0.5 || lo.y > 0.5 || hi.x < size.x - 0.5 || hi.y < size.y - 0.5;
    bool own = turned || (inside && cut);
    float2 q = coord;
    float2 full = size;
    float2 edge = float2(1.5);
    if (own) {
        float3 w = toLayer * float3(coord, 1.0);
        if (w.z <= 0.0) return half4(0);
        q = w.xy / w.z;
        full = layer;
        edge = 0.5 + 1.5 / max(float2(length(fromLayer[0].xy), length(fromLayer[1].xy)), float2(0.0001));
    }
    float2 t = (q / full - offset) / max(scale, 0.02);
    float2 f = fract(t);
    if (mirror > 0.5) f = mix(f, 1 - f, mod(floor(t), 2));
    float2 s = clamp(f * full, min(edge, full * 0.5), max(full - edge, full * 0.5));
    if (!own) return image.eval(s);
    float3 g = fromLayer * float3(s, 1.0);
    return image.eval(g.xy / g.z);
}
